-- Synced app data. Ids are generated by the app (uuid) so rows can be created offline;
-- deletions are soft (deleted_at) so other devices learn about them on their next sync,
-- and updated_at drives incremental sync ("give me everything changed since X").

create table public.accounts (
    id               uuid primary key default gen_random_uuid(),
    household_id     uuid not null references public.households(id) on delete cascade,
    name             text not null check (length(trim(name)) between 1 and 100),
    starting_balance numeric(14,2) not null default 0,
    color_hex        text not null default '#76C893' check (color_hex ~ '^#[0-9A-Fa-f]{6}$'),
    monthly_salary   numeric(14,2) not null default 0 check (monthly_salary >= 0),
    created_at       timestamptz not null default now(),
    updated_at       timestamptz not null default now(),
    deleted_at       timestamptz,
    unique (id, household_id)
);
create index accounts_household_sync_idx on public.accounts(household_id, updated_at);

create table public.net_worth_entries (
    id           uuid primary key default gen_random_uuid(),
    household_id uuid not null references public.households(id) on delete cascade,
    account_id   uuid not null,
    value        numeric(14,2) not null,
    entry_date   date not null,
    note         text not null default '' check (length(note) <= 1000),
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now(),
    deleted_at   timestamptz,
    -- The account must belong to the same household
    foreign key (account_id, household_id) references public.accounts(id, household_id) on delete cascade
);
create index net_worth_entries_household_sync_idx on public.net_worth_entries(household_id, updated_at);
create index net_worth_entries_account_date_idx on public.net_worth_entries(account_id, entry_date);

create table public.fixed_expenses (
    id           uuid primary key default gen_random_uuid(),
    household_id uuid not null references public.households(id) on delete cascade,
    title        text not null check (length(trim(title)) between 1 and 200),
    note         text not null default '' check (length(note) <= 1000),
    cost         numeric(14,2) not null check (cost >= 0),
    expense_date date,
    recurrence   text not null default 'MONTHLY' check (recurrence in ('MONTHLY', 'ANNUAL')),
    -- Accounts that share the expense; empty = all accounts of the household
    account_ids  uuid[] not null default '{}',
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now(),
    deleted_at   timestamptz
);
create index fixed_expenses_household_sync_idx on public.fixed_expenses(household_id, updated_at);

-- Categories the user picked in Expense Analysis, keyed by normalised expense name
create table public.category_feedback (
    household_id uuid not null references public.households(id) on delete cascade,
    name_key     text not null check (length(name_key) between 1 and 200),
    category     text not null check (category in (
        'SUBSCRIPTIONS', 'HOUSING', 'TRANSPORT', 'DINING_LEISURE', 'TRAVEL', 'GROCERIES', 'HEALTH',
        'FINANCE', 'EDUCATION', 'SHOPPING_PERSONAL', 'KIDS_PETS', 'OTHER')),
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now(),
    deleted_at   timestamptz,
    primary key (household_id, name_key)
);
create index category_feedback_household_sync_idx on public.category_feedback(household_id, updated_at);

-- Fixed expenses may only reference accounts of their own household
create or replace function public.check_fixed_expense_accounts()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    if exists (
        select 1 from unnest(new.account_ids) as a(id)
        where not exists (
            select 1 from public.accounts acc where acc.id = a.id and acc.household_id = new.household_id
        )
    ) then
        raise exception 'account_ids must belong to the expense''s household' using errcode = '23503';
    end if;
    return new;
end;
$$;

create trigger fixed_expenses_check_accounts
    before insert or update of account_ids, household_id on public.fixed_expenses
    for each row execute function public.check_fixed_expense_accounts();

create trigger accounts_updated_at before update on public.accounts
    for each row execute function public.set_updated_at();
create trigger net_worth_entries_updated_at before update on public.net_worth_entries
    for each row execute function public.set_updated_at();
create trigger fixed_expenses_updated_at before update on public.fixed_expenses
    for each row execute function public.set_updated_at();
create trigger category_feedback_updated_at before update on public.category_feedback
    for each row execute function public.set_updated_at();

-- ── Row level security: members of a household share all of its data ───────

alter table public.accounts enable row level security;
alter table public.net_worth_entries enable row level security;
alter table public.fixed_expenses enable row level security;
alter table public.category_feedback enable row level security;

do $$
declare
    t text;
begin
    foreach t in array array['accounts', 'net_worth_entries', 'fixed_expenses', 'category_feedback'] loop
        execute format(
            'create policy "Members read %1$s" on public.%1$I for select to authenticated
                 using (public.is_household_member(household_id))', t);
        execute format(
            'create policy "Members add %1$s" on public.%1$I for insert to authenticated
                 with check (public.is_household_member(household_id))', t);
        execute format(
            'create policy "Members change %1$s" on public.%1$I for update to authenticated
                 using (public.is_household_member(household_id))
                 with check (public.is_household_member(household_id))', t);
        execute format(
            'create policy "Members delete %1$s" on public.%1$I for delete to authenticated
                 using (public.is_household_member(household_id))', t);
        execute format('revoke all on public.%I from anon', t);
    end loop;
end;
$$;

-- Household members can see each other's names
create policy "Members read co-members' profiles" on public.profiles
    for select to authenticated using (
        exists (
            select 1
            from public.household_members mine
            join public.household_members theirs on theirs.household_id = mine.household_id
            where mine.user_id = (select auth.uid()) and theirs.user_id = profiles.user_id
        )
    );
